# Mock function for testing
def calculate_stock_volatility(prices):
    # Super simple: std deviation on small sample sets, or 0 if size 1 or prices empty
    if not prices or len(prices) == 1:
        return 0.0
    mean = sum(prices) / len(prices)
    variance = sum((p - mean) ** 2 for p in prices) / (len(prices) - 1)
    return variance ** 0.5

# Insert your function here for local testing
def portfolio_risk_assessment(portfolio):
    '''
    Load previous session and create portfolio_risk_assessment function. Takes a dict where keys are stock names and values have 'prices' list and 'allocation' float. For each stock, call calculate_stock_volatility(prices), multiply by allocation, sum all weighted volatilities. Returns: float representing total portfolio risk as weighted sum.
    '''
    total_risk = 0.0
    for stock in portfolio:
        prices = portfolio[stock]['prices']
        allocation = portfolio[stock]['allocation']
        volatility = calculate_stock_volatility(prices)
        total_risk += volatility * allocation
    return total_risk


